using System.Collections.ObjectModel;using Finora.Application;using Finora.Domain;namespace Finora.App;public sealed class ReportsViewModel:ViewModelBase{private readonly IFinanceStore _store;private readonly IAppSettingsService _settings;private string _summary="";public ReportsViewModel(IFinanceStore store,IAppSettingsService settings){_store=store;_settings=settings;RefreshCommand=new AsyncCommand(LoadAsync);}public ObservableCollection<CategorySpend> Categories{get;}=[];public string Summary{get=>_summary;private set=>SetProperty(ref _summary,value);}public System.Windows.Input.ICommand RefreshCommand{get;}public Task LoadAsync()=>RunAsync(async()=>{var today=DateOnly.FromDateTime(DateTime.Today);var start=new DateOnly(today.Year,today.Month,1);var s=await _store.GetDashboardAsync(start,start.AddMonths(1).AddDays(-1));Categories.Clear();foreach(var i in s.TopCategories)Categories.Add(i);Summary=$"This month: income {new Money(s.IncomeMinor,_settings.DefaultCurrency).Format()}; spending {new Money(Math.Abs(s.ExpenseMinor),_settings.DefaultCurrency).Format()}; net change {new Money(s.NetChangeMinor,_settings.DefaultCurrency).Format()}. "+(Categories.Count==0?"No categorized spending is available yet.":$"Top category: {Categories[0].CategoryName}.");});}
